package com.nopilot.aiservice.service;  import org.springframework.stereotype.Component;  import java.util.regex.Pattern;  /**  * NoPilot explains code; it does not write or modify it. A question that is really a  * command to produce or change code is answered with a fixed message and never reaches  * the LLM, which also saves tokens. Deliberately narrow: only imperative requests at the  * start of the question match ("How is X implemented?" is a normal question).  */ @Component public class RequestPolicy {      public static final String REFUSAL =             "NoPilot explains existing code; it does not write, fix or modify code. "                     + "Try asking how something works, where it is defined, or what it depends on.";      private static final Pattern CODE_CHANGE_REQUEST = Pattern.compile(             "^\\s*(please\\s+|can you\\s+|could you\\s+|would you\\s+)?"                     + "(write|implement|generate|create|add|fix|refactor|rewrite|modify|change|build|patch|update)\\b",             Pattern.CASE_INSENSITIVE);      public boolean isCodeChangeRequest(String question) {         return question != null && CODE_CHANGE_REQUEST.matcher(question).find();     } }
